"""json2csv.py — Convert JSON array from stdin to CSV on stdout.

Usage: cat data.json | python json2csv.py
"""

import csv
import json
import sys


def collect_keys(objects):
    """Return the union of all keys across all objects, preserving insertion order."""
    keys = []
    seen = set()
    for obj in objects:
        for key in obj:
            if key not in seen:
                seen.add(key)
                keys.append(key)
    return keys


def stringify_value(value):
    """Convert a value to its CSV cell representation.

    Nested dicts/lists are stringified as JSON; everything else uses str().
    """
    if isinstance(value, (dict, list)):
        return json.dumps(value, ensure_ascii=False)
    if value is None:
        return ""
    return str(value)


def main():
    try:
        raw = sys.stdin.read()
    except Exception as e:
        print(f"Error reading input: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        data = json.loads(raw)
    except json.JSONDecodeError as e:
        print(f"Error parsing JSON: {e}", file=sys.stderr)
        sys.exit(1)

    if not isinstance(data, list):
        print("Error: input must be a JSON array", file=sys.stderr)
        sys.exit(1)

    # Collect all keys (union across objects)
    keys = collect_keys(data)

    writer = csv.writer(sys.stdout, lineterminator="\r\n")
    # Write header
    writer.writerow(keys)

    # Write data rows
    for obj in data:
        row = [stringify_value(obj.get(key, "")) for key in keys]
        writer.writerow(row)


if __name__ == "__main__":
    main()
"}

